    stamper.close();
    reader.close();
    mFileList.add(new File(finalOutputFile));
}

/**
 * Returns a file path that does not exist yet. If a file with the given
 * path already exists, an unique number is appended to the file name
 * (before the extension), e.g. {@code abc_encrypted(1).pdf}.
 *
 * @param path the desired output file path
 * @return an unique, currently unused file path
 */
private String getUniqueFileName(String path) {
    File file = new File(path);
    if (!file.exists()) {
        return path;
    }

    int dotIndex = path.lastIndexOf('.');
    String baseName = dotIndex == -1 ? path : path.substring(0, dotIndex);
    String extension = dotIndex == -1 ? "" : path.substring(dotIndex);

    int counter = 1;
    String uniquePath = String.format(Locale.US, "%s(%d)%s", baseName, counter, extension);
    while (new File(uniquePath).exists()) {
        counter++;
        uniquePath = String.format(Locale.US, "%s(%d)%s", baseName, counter, extension);
    }

    return uniquePath;
}

